// Erzeugt von medikamente/scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"dabigatran":{"wirkmechanismus":"Hemmt die Blutgerinnung, indem es das zentrale Gerinnungsenzym Thrombin direkt blockiert. Eingenommen wird die unwirksame Vorstufe Dabigatranetexilat (Prodrug), die im Körper durch Esterasen rasch in Dabigatran umgewandelt wird. Dabigatran hemmt freies und an Gerinnsel gebundenes Thrombin reversibel und verhindert so die Bildung von Fibrin und die thrombinbedingte Aktivierung der Blutplättchen. Es wird zu rund 80 % unverändert über die Nieren ausgeschieden; als spezifisches Gegenmittel steht Idarucizumab zur Verfügung.","nebenwirkungen":{"haeufig":["Anämie (Blutarmut)","Nasenbluten","Magen-Darm-Blutungen","Bauchschmerzen, Durchfall, Verdauungsbeschwerden, Übelkeit","Hautblutungen","Blutungen der Harn- und Geschlechtsorgane, Blut im Urin"],"gelegentlich":["Hirnblutung","Thrombozytopenie (verminderte Blutplättchen)","Überempfindlichkeit, Hautausschlag, Juckreiz","Blutergüsse (Hämatome), Bluthusten","Magen-Darm-Geschwüre, Entzündung der Speiseröhre, Reflux, Schluckbeschwerden, Erbrechen","Blutungen aus Enddarm und Hämorrhoiden","Leberfunktionsstörung, erhöhte Leberwerte"],"selten":["Anaphylaktische Reaktion, Angioödem, Nesselsucht","Gelenkblutungen","Blutungen an Einstich-, Katheter- und Wundstellen"],"unbekannt":["Agranulozytose, Neutropenie (Mangel an weissen Blutkörperchen)","Bronchospasmus","Haarausfall"]},"schwangerschaft":"Nicht anwenden, ausser wenn eindeutig erforderlich. Frauen im gebärfähigen Alter sollen während der Behandlung eine Schwangerschaft vermeiden.","stillzeit":"Keine Daten beim Menschen – während der Behandlung nicht stillen.","hinweise":["Kapseln ganz mit Wasser schlucken, nicht öffnen oder zerkauen – der Inhalt wird sonst viel stärker aufgenommen (Blutungsgefahr).","Kapseln in der Originalverpackung (Blister) lassen und vor Feuchtigkeit schützen.","Nierenfunktion vor Beginn und regelmässig kontrollieren lassen, bei älteren Menschen mindestens jährlich.","Nicht eigenmächtig absetzen; vor Operationen, Zahnbehandlungen und neuen Medikamenten Arzt oder Apotheke informieren."],"darreichung":["Hartkapseln"]},"dalteparin":{"wirkmechanismus":"Hemmt die Blutgerinnung und verhindert so, dass sich Blutgerinnsel bilden oder vergrössern. Dalteparin ist ein aus Heparin gewonnenes niedermolekulares Heparin: Es verstärkt die Wirkung des körpereigenen Hemmstoffs Antithrombin, der vor allem den Gerinnungsfaktor Xa und in geringerem Mass Thrombin (Faktor IIa) blockiert. Im Vergleich zu unfraktioniertem Heparin wirkt es gleichmässiger und länger, sodass ein bis zwei Spritzen unter die Haut pro Tag genügen. Die Wirkung lässt sich über die Anti-Xa-Aktivität messen; die Ausscheidung erfolgt überwiegend über die Nieren.","nebenwirkungen":{"haeufig":["Blutungen","Bluterguss (Hämatom) und Schmerzen an der Einstichstelle","Leichte, meist vorübergehende Abnahme der Blutplättchen (Thrombozytopenie Typ I)","Vorübergehender Anstieg der Leberwerte (Transaminasen)"],"gelegentlich":["Überempfindlichkeitsreaktionen"],"selten":["Hautnekrosen (absterbende Haut) an der Einstichstelle","Vorübergehender Haarausfall"],"unbekannt":["Heparininduzierte Thrombozytopenie Typ II (HIT; immunbedingt, mit oder ohne Thrombosen)","Anaphylaktische Reaktionen","Hirnblutungen und Blutungen im hinteren Bauchraum (retroperitoneal), teils tödlich","Spinale oder epidurale Hämatome nach rückenmarksnaher Anästhesie mit möglicher Lähmung","Hautausschlag"]},"schwangerschaft":"Dalteparin passiert die Plazenta nicht; bisherige Erfahrungen zeigen kein erhöhtes Fehlbildungsrisiko. Anwendung nach ärztlicher Abwägung möglich; eine rückenmarksnahe Anästhesie bei der Geburt muss zeitlich abgestimmt werden.","stillzeit":"Geht in geringen Mengen in die Muttermilch über und wird vom Säugling über den Darm kaum aufgenommen; Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Unter die Haut spritzen (meist am Bauch), nie in den Muskel; Einstichstelle wechseln und nicht reiben.","Blutplättchen vor und während der Behandlung kontrollieren lassen (heparininduzierte Thrombozytopenie).","Vor Operationen, Zahnbehandlungen und Spinal- oder Periduralanästhesie die Behandlung angeben.","Bei Blutungszeichen (schwarzer Stuhl, Blut im Urin, ungewöhnliche Blutergüsse) sofort ärztlichen Rat holen."],"darreichung":["Injektionslösung in Fertigspritzen","Injektionslösung in Ampullen"]},"dapagliflozin":{"wirkmechanismus":"Senkt den Blutzucker, indem die Nieren überschüssigen Zucker mit dem Urin ausscheiden. Dapagliflozin hemmt selektiv und reversibel den Natrium-Glukose-Cotransporter 2 (SGLT2) im proximalen Nierentubulus, der normalerweise den grössten Teil der gefilterten Glukose in den Körper zurückholt. Die Wirkung ist unabhängig vom Insulin; zusätzlich entstehen eine leichte osmotische Diurese, eine vermehrte Natriumausscheidung, ein Kalorienverlust und eine mässige Blutdrucksenkung. Bei Herz- und Nierenkrankheit tragen vermutlich die Senkung des Drucks in den Nierenkörperchen (tubuloglomerulärer Feedback) und die Entlastung des Herzens zur Schutzwirkung bei.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung) bei Kombination mit Insulin oder Sulfonylharnstoffen"],"haeufig":["Genitalinfektionen wie Scheidenpilz (Vulvovaginitis) oder Eichelentzündung (Balanitis)","Harnwegsinfekte","Vermehrtes Wasserlassen (Polyurie), Brennen beim Wasserlassen (Dysurie)","Schwindel","Hautausschlag","Rückenschmerzen","Anstieg von Hämatokrit und Blutfetten, vorübergehender Rückgang der Nierenfunktion zu Therapiebeginn"],"gelegentlich":["Volumenmangel (Austrocknung, tiefer Blutdruck)","Durst, Mundtrockenheit","Verstopfung","Nächtliches Wasserlassen (Nykturie)","Juckreiz im Genitalbereich","Gewichtsabnahme","Anstieg von Kreatinin und Harnstoff im Blut"],"selten":["Diabetische Ketoazidose (lebensbedrohliche Übersäuerung, auch bei fast normalem Blutzucker)"],"sehrSelten":["Fournier-Gangrän (nekrotisierende Fasziitis im Genital- und Dammbereich)","Angioödem (Schwellung von Gesicht, Lippen, Zunge)","Tubulointerstitielle Nephritis (Nierenentzündung)"]},"schwangerschaft":"Nicht anwenden: im 2. und 3. Schwangerschaftsdrittel nicht empfohlen (Nierenschäden im Tierversuch). Bei Eintritt einer Schwangerschaft absetzen und ärztlich auf eine andere Behandlung umstellen.","stillzeit":"Nicht anwenden, da ein Übergang in die Muttermilch und Auswirkungen auf das gestillte Kind nicht ausgeschlossen werden können.","hinweise":["Der Urin-Zuckertest fällt unter der Behandlung immer positiv aus – zur Kontrolle den Blutzucker messen.","Bei akuten Erkrankungen mit Erbrechen, Durchfall oder wenig Trinken sowie vor grösseren Operationen nach ärztlicher Anweisung pausieren (Ketoazidose- und Austrocknungsgefahr).","Warnzeichen einer Ketoazidose (Übelkeit, Erbrechen, Bauchschmerzen, starker Durst, rasche Atmung, Verwirrtheit, ungewöhnliche Müdigkeit) sofort ärztlich abklären lassen.","Ausreichend trinken und auf Intimhygiene achten; Einnahme einmal täglich, unabhängig von den Mahlzeiten."],"darreichung":["Filmtabletten","Retardtabletten (Kombination mit Metformin)"]},"daptomycin":{"wirkmechanismus":"Durchlöchert die Hülle von Bakterien und tötet sie rasch ab. Daptomycin lagert sich calciumabhängig in die Zellmembran grampositiver Bakterien ein, führt zu einer raschen Depolarisation und stoppt die Synthese von DNA, RNA und Eiweissen. Es wirkt auch gegen Methicillin-resistente Staphylokokken (MRSA) und Vancomycin-resistente Enterokokken. In der Lunge wird es durch das Surfactant inaktiviert und ist deshalb gegen Lungenentzündungen unwirksam.","nebenwirkungen":{"haeufig":["Pilzinfektionen, Harnwegsinfektionen","Anämie (Blutarmut)","Angst, Schlaflosigkeit","Schwindel, Kopfschmerzen","Bluthochdruck oder tiefer Blutdruck","Übelkeit, Erbrechen, Bauchschmerzen, Durchfall, Verstopfung, Blähungen","Erhöhte Leberwerte und erhöhte Kreatinkinase (CK)","Ausschlag, Juckreiz, Gliederschmerzen, Reaktionen an der Infusionsstelle, Fieber"],"gelegentlich":["Eosinophilie, Thrombozythämie, erhöhte INR","Appetitlosigkeit, Hyperglykämie, Elektrolytstörungen","Kribbeln, Geschmacksstörungen, Zittern","Herzrhythmusstörungen (supraventrikuläre Tachykardie, Extrasystolen)","Myositis, Muskelschwäche, Muskel- und Gelenkschmerzen","Nierenfunktionsstörung bis Nierenversagen","Nesselsucht"],"selten":["Gelbsucht (Ikterus)","Verlängerte Prothrombinzeit"],"unbekannt":["Rhabdomyolyse (Muskelzerfall)","Eosinophile Pneumonie, organisierende Pneumonie","Anaphylaxie, Angioödem, DRESS (schwere Arzneimittelreaktion)","Schwere bullöse Hautreaktionen, akute generalisierte exanthematische Pustulose (AGEP)","Periphere Neuropathie","Clostridioides-difficile-assoziierte Durchfälle","Tubulointerstitielle Nephritis"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur bei eindeutiger Notwendigkeit anwenden.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung in der Stillzeit nur nach ärztlicher Abwägung, Stillen allenfalls unterbrechen.","hinweise":["Wird im Spital oder ambulant als Infusion bzw. Injektion einmal täglich verabreicht.","Muskelschmerzen, Muskelschwäche, Kribbeln oder Taubheit sowie neue Atemnot mit Fieber sofort melden.","Kreatinkinase (CK) wird mindestens wöchentlich kontrolliert, bei Risikopatienten häufiger."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"darbepoetin-alfa":{"wirkmechanismus":"Regt das Knochenmark an, mehr rote Blutkörperchen zu bilden. Darbepoetin alfa wirkt wie das körpereigene Hormon Erythropoetin am Erythropoetin-Rezeptor der Vorläuferzellen im Knochenmark. Durch zwei zusätzliche Zuckerketten im Molekül wird es langsamer abgebaut und hat eine etwa dreimal längere Halbwertszeit als Epoetin alfa. Deshalb genügen Spritzen in Abständen von einer bis vier Wochen; ausreichend Eisen ist Voraussetzung für die Wirkung.","nebenwirkungen":{"sehrHaeufig":["Bluthochdruck (bei Nierenkranken)","Überempfindlichkeitsreaktionen (z. B. Hautausschlag, Nesselsucht)","Wassereinlagerungen (Ödeme, bei Krebspatienten)"],"haeufig":["Schlaganfall (bei Nierenkranken)","Thrombosen und Embolien, inkl. Lungenembolie (bei Krebspatienten)","Hautrötung (Erythem)","Schmerzen an der Injektionsstelle"],"gelegentlich":["Krampfanfälle","Thrombose des Dialyse-Shunts"],"unbekannt":["Erythroblastopenie (PRCA) durch Antikörper gegen Erythropoetin","Hypertensive Krise mit Hirnfunktionsstörung (Enzephalopathie)","Anaphylaxie, Angioödem (Schwellung von Gesicht und Rachen)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)"]},"schwangerschaft":"Nur nach strenger ärztlicher Nutzen-Risiko-Abwägung; Erfahrungen beim Menschen fehlen weitgehend.","stillzeit":"Nicht bekannt, ob Darbepoetin in die Muttermilch übergeht; Anwendung nur nach Abwägung.","hinweise":["Blutdruck regelmässig messen; bei starken Kopfschmerzen, Verwirrtheit oder Sehstörungen sofort ärztliche Hilfe holen.","Hämoglobin und Eisenwerte werden regelmässig kontrolliert; meist ist zusätzlich Eisen nötig.","Im Kühlschrank (2–8 °C) lagern, nicht einfrieren oder schütteln.","Missbrauch als Dopingmittel ist verboten und gefährlich (Thrombosen, Herzinfarkt)."],"darreichung":["Injektionslösung in Fertigspritzen und Fertigpens (Spritze unter die Haut oder in die Vene)"]},"darunavir":{"wirkmechanismus":"Verhindert, dass neu gebildete HI-Viren reifen und weitere Zellen infizieren. Darunavir hemmt die HIV-1-Protease, ein Enzym, das die viralen Gag-Pol-Vorläuferproteine in funktionsfähige Einzelproteine zerschneidet; es entstehen nur unreife, nicht infektiöse Viruspartikel. Darunavir bindet sehr fest an das Enzym und wirkt auch bei vielen Resistenzen gegen ältere Proteasehemmer. Weil es rasch über CYP3A4 abgebaut wird, wird es immer mit einem «Booster» (Ritonavir oder Cobicistat) kombiniert, der diesen Abbau hemmt – das erklärt die zahlreichen Wechselwirkungen.","nebenwirkungen":{"sehrHaeufig":["Durchfall"],"haeufig":["Übelkeit, Erbrechen, Bauchschmerzen, Blähungen, Verdauungsbeschwerden","Kopfschmerzen, Schwindel","Periphere Neuropathie (Kribbeln, Taubheitsgefühl)","Schlaflosigkeit","Hautausschlag, Juckreiz","Erhöhte Blutfette (Cholesterin, Triglyceride), Diabetes mellitus","Erhöhte Leberwerte (ALT) und Amylase","Müdigkeit, Schwäche"],"gelegentlich":["Hepatitis (Leberentzündung)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Herzinfarkt, Angina pectoris, QT-Verlängerung","Angioödem, Nesselsucht","Thrombozytopenie, Neutropenie, Anämie","Depression, Angst, Desorientierung","Akutes Nierenversagen, Nierensteine","Osteonekrose, Muskelschmerzen, Gynäkomastie (Brustvergrösserung beim Mann)"],"selten":["Stevens-Johnson-Syndrom","DRESS (schwere Arzneimittelreaktion mit Eosinophilie und Organbeteiligung)","Erythema multiforme","Krampfanfälle, Ohnmacht","Kristallnephropathie (Ablagerung von Darunavir-Kristallen in der Niere)"],"unbekannt":["Toxische epidermale Nekrolyse","Akute generalisierte exanthematische Pustulose (AGEP)"]},"schwangerschaft":"Darunavir mit Ritonavir kann in der Schwangerschaft angewendet werden, wenn der Nutzen das Risiko rechtfertigt. Darunavir mit Cobicistat wird wegen zu tiefer Spiegel in der Schwangerschaft nicht empfohlen.","stillzeit":"HIV-positive Mütter sollen grundsätzlich nicht stillen (Übertragungsrisiko); ein Stillwunsch ist mit der HIV-Fachperson zu besprechen.","hinweise":["Immer zusammen mit Ritonavir oder Cobicistat und mit einer Mahlzeit einnehmen (bessere Aufnahme).","Vor jedem neuen Medikament – auch rezeptfreien und pflanzlichen wie Johanniskraut – mit Ärztin, Arzt oder Apotheke Rücksprache nehmen.","Täglich ohne Unterbrechung einnehmen, damit keine Resistenzen entstehen.","Bei schwerem Hautausschlag mit Fieber, Blasen oder Schleimhautbeteiligung sofort ärztlich melden."],"darreichung":["Filmtabletten"]},"desmopressin":{"wirkmechanismus":"Bewirkt, dass die Nieren mehr Wasser zurückhalten und weniger, dafür konzentrierteren Urin bilden. Desmopressin ist ein synthetisch abgewandeltes Vasopressin (antidiuretisches Hormon) und aktiviert gezielt die V2-Rezeptoren in den Sammelrohren der Niere; dadurch werden Wasserkanäle (Aquaporine) eingebaut und Wasser zurückgewonnen. Im Gegensatz zu Vasopressin wirkt es kaum gefässverengend und deutlich länger. In höherer Dosis setzt es zudem Gerinnungsfaktor VIII und von-Willebrand-Faktor aus den Gefässwänden frei und verbessert so die Blutgerinnung.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Hyponatriämie (Natriummangel im Blut), v. a. bei Erwachsenen über 65 Jahre","Schwindel","Übelkeit, Bauchschmerzen, Durchfall, Verstopfung, Erbrechen","Mundtrockenheit","Ödeme (Wassereinlagerungen), Müdigkeit"],"gelegentlich":["Schlaflosigkeit oder Schläfrigkeit","Herzklopfen, Blutdruckabfall beim Aufstehen","Hautausschlag, Juckreiz","Muskelkrämpfe","Gewichtszunahme","Stimmungsschwankungen, Aggressivität (bei Kindern)"],"selten":["Verwirrtheit"],"unbekannt":["Schwere Hyponatriämie mit Krampfanfällen, Hirnödem und Bewusstlosigkeit (Wasservergiftung)","Anaphylaktische Reaktionen","Gesichtsrötung, Pulsanstieg und Blutdruckschwankungen nach Injektion"]},"schwangerschaft":"Nur nach ärztlicher Abwägung. Die Erfahrungen bei Schwangeren mit Diabetes insipidus zeigen keine schädlichen Wirkungen auf Schwangerschaft oder Kind.","stillzeit":"Geht nur in sehr geringen Mengen in die Muttermilch über; Stillen ist in der Regel möglich.","hinweise":["Bei Bettnässen und Nykturie ab 1 Stunde vor bis 8 Stunden nach der Einnahme möglichst wenig trinken – sonst droht eine Wasservergiftung.","Bei Erbrechen, Durchfall, Fieber oder starkem Durst die Einnahme unterbrechen; bei Kopfschmerzen, Übelkeit, Verwirrtheit oder rascher Gewichtszunahme sofort ärztlich das Natrium kontrollieren lassen.","Schmelztabletten unter der Zunge zergehen lassen, ohne Wasser; Tabletten, Schmelztabletten und Nasenspray sind unterschiedlich dosiert und nicht 1:1 austauschbar."],"darreichung":["Tabletten","Schmelztabletten (Lyophilisat)","Nasenspray","Injektionslösung"]},"desogestrel":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem der Eisprung unterdrückt wird. Desogestrel ist eine Vorstufe (Prodrug) und wird in Darmwand und Leber zum eigentlichen Wirkstoff Etonogestrel umgewandelt. In der Dosis von 75 Mikrogramm täglich hemmt es – anders als ältere Minipillen – in den allermeisten Zyklen den Eisprung; zusätzlich verdickt es den Schleim am Gebärmutterhals. Da kein Östrogen enthalten ist, steigt das Thromboserisiko nach heutigem Wissen kaum.","nebenwirkungen":{"haeufig":["Unregelmässige Blutungen, Ausbleiben der Regel","Stimmungsschwankungen, depressive Verstimmung, verminderte Libido","Kopfschmerzen","Übelkeit","Akne","Brustschmerzen","Gewichtszunahme"],"gelegentlich":["Scheideninfektion","Unverträglichkeit von Kontaktlinsen","Erbrechen","Haarausfall","Schmerzhafte Regelblutung, Eierstockzysten","Müdigkeit"],"selten":["Hautausschlag, Nesselsucht","Erythema nodosum (entzündliche Hautknoten)"],"unbekannt":["Überempfindlichkeitsreaktionen bis Angioödem","Absonderung aus der Brust"]},"schwangerschaft":"Kontraindiziert; bei Eintritt einer Schwangerschaft absetzen. Eine versehentliche Einnahme erhöht das Fehlbildungsrisiko nach heutigem Wissen nicht.","stillzeit":"Erlaubt: Milchmenge und -qualität werden nicht beeinträchtigt; sehr geringe Mengen gehen in die Muttermilch über.","hinweise":["Täglich etwa zur gleichen Zeit ohne Pause einnehmen. Bei mehr als 12 Stunden Verspätung ist der Schutz vermindert: Tablette sofort nachnehmen und 7 Tage zusätzlich ein Kondom verwenden.","Erbrechen oder starker Durchfall innerhalb von 3–4 Stunden nach der Einnahme gilt wie eine vergessene Tablette.","Unregelmässige Blutungen sind häufig, besonders in den ersten Monaten; anhaltende oder starke Blutungen ärztlich abklären.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Filmtabletten"]},"dexamethason":{"wirkmechanismus":"Dämpft Entzündungen, allergische Reaktionen und die Abwehrreaktionen des Immunsystems sehr stark. Dexamethason ist ein synthetisches Glukokortikoid, das an den Glukokortikoid-Rezeptor im Zellinneren bindet und die Ablesung zahlreicher Gene verändert: Entzündungsbotenstoffe wie Zytokine und Prostaglandine werden vermindert gebildet, Abwehrzellen gehemmt und durchlässige Gefässe abgedichtet. Es wirkt etwa 25- bis 30-mal stärker entzündungshemmend als körpereigenes Cortisol, hat praktisch keine salzzurückhaltende (mineralokortikoide) Wirkung und wirkt lange. Darum eignet es sich besonders bei Hirnödem und zur Vorbeugung von Übelkeit bei Chemotherapie.","nebenwirkungen":{"sehrHaeufig":["Erhöhter Augeninnendruck und Bindehautblutung (Augenimplantat)"],"haeufig":["Katarakt (grauer Star), Augenschmerzen, Glaskörpertrübungen (Augenimplantat)","Augenbeschwerden wie Brennen und Stechen (Augentropfen)"],"unbekannt":["Erhöhte Infektanfälligkeit und Verschleierung von Infektionen","Erhöhter Blutzucker bis zum Steroiddiabetes","Cushing-Syndrom (Vollmondgesicht, Stammfettsucht), Gewichtszunahme","Osteoporose, Knochennekrose (z. B. Hüftkopf), Muskelschwäche, Sehnenriss","Magen-Darm-Geschwüre und -Blutungen, Pankreatitis","Psychische Störungen (Schlaflosigkeit, Euphorie, Unruhe, Depression, Psychose)","Bluthochdruck, Wassereinlagerungen, Kaliummangel","Nebennierenrindeninsuffizienz nach dem Absetzen, Wachstumshemmung bei Kindern","Dünne Haut, Akne, verzögerte Wundheilung; grauer und grüner Star bei längerer Anwendung"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Dexamethason gelangt über die Plazenta zum Kind; bei längerer Behandlung sind Wachstumsverzögerung und eine Unterfunktion der Nebennieren beim Neugeborenen möglich.","stillzeit":"Geht in die Muttermilch über. Bei kurzer Anwendung meist vertretbar; bei höheren Dosen oder Langzeitbehandlung ärztlich abklären, ob abgestillt werden soll.","hinweise":["Tabletten morgens mit dem Frühstück einnehmen (weniger Magenbeschwerden und Schlafstörungen).","Nach längerer Behandlung nicht abrupt absetzen, sondern nach ärztlichem Schema ausschleichen (Gefahr einer Nebennierenkrise).","Bei längerer Einnahme Blutzucker, Blutdruck, Augeninnendruck und Knochengesundheit kontrollieren lassen; auf ausreichend Calcium und Vitamin D achten.","Augentropfen nur kurzzeitig und unter augenärztlicher Kontrolle anwenden; weiche Kontaktlinsen vorher herausnehmen."],"darreichung":["Tabletten","Injektionslösung","Augentropfen","Intravitreales Implantat (Augenimplantat)"]},"dexpanthenol":{"wirkmechanismus":"Fördert die Regeneration von Haut und Schleimhäuten. Dexpanthenol wird in der Haut rasch in Pantothensäure (Vitamin B5) umgewandelt, einen Baustein des Coenzyms A, das die Zellen für Stoffwechsel und Zellteilung brauchen. Es regt die Neubildung der obersten Hautschicht (Epithelisierung) an, verbessert die Feuchtigkeitsbindung der Haut und lindert Juckreiz leicht.","nebenwirkungen":{"unbekannt":["Allergische Reaktionen","Kontaktdermatitis, Ekzem an der Auftragsstelle","Juckreiz, Rötung, Ausschlag oder Nesselsucht","Hautreizung, Bläschen"]},"schwangerschaft":"Kann angewendet werden; bei bestimmungsgemässer Anwendung sind keine Risiken bekannt.","stillzeit":"Kann angewendet werden, auch zur Pflege wunder Brustwarzen. Bepanthen Plus (mit Chlorhexidin) nicht auf die Brustwarzen auftragen.","hinweise":["Wunden, die sich nach einigen Tagen nicht bessern oder Entzündungszeichen zeigen (Rötung, Schwellung, Eiter, Fieber), ärztlich beurteilen lassen.","Bepanthen Plus enthält das Desinfektionsmittel Chlorhexidin: nicht zusammen mit Seifen oder anderen Desinfektionsmitteln auf derselben Stelle anwenden.","Augen- und Nasensalbe: nach dem Einbringen ins Auge kurzzeitig verschwommenes Sehen – erst wieder Auto fahren, wenn die Sicht klar ist."],"darreichung":["Salbe","Creme","Augen- und Nasensalbe"]},"dienogest":{"wirkmechanismus":"Lässt Endometriose-Herde schrumpfen, indem es eine dauerhafte Gestagenwirkung erzeugt und die Östrogenbildung dämpft. Dienogest bindet stark an Progesteronrezeptoren und wirkt an der Gebärmutterschleimhaut kräftig gestagen; zugleich hat es eine antiandrogene, aber keine androgene Wirkung. Bei täglicher Einnahme senkt es die Hormonausschüttung der Eierstöcke mässig, sodass ein östrogenarmes, gestagenbetontes Milieu entsteht. Das Gewebe der Endometrioseherde wird zunächst umgewandelt (Dezidualisierung) und bildet sich dann zurück.","nebenwirkungen":{"haeufig":["Uterine Blutungen, Schmierblutungen, verändertes Blutungsmuster","Kopfschmerzen, Migräne","Depressive Verstimmung, Stimmungsschwankungen, Schlafstörungen, Nervosität, Reizbarkeit","Libidoverlust","Brustbeschwerden","Gewichtszunahme","Übelkeit, Bauchschmerzen, Blähungen","Akne, Haarausfall","Hitzewallungen","Ovarialzysten (Eierstockzysten)","Rückenschmerzen, Schwäche"],"gelegentlich":["Anämie (Blutarmut)","Angst, Depression","Trockene Augen, Ohrensausen","Herzklopfen, tiefer Blutdruck","Atemnot","Durchfall, Verstopfung","Trockene Haut, Juckreiz, vermehrte Behaarung","Scheidenpilz, Harnwegsinfektionen","Wassereinlagerungen (Ödeme)"]},"schwangerschaft":"Nicht anwenden: Eine Endometriose muss in der Schwangerschaft nicht behandelt werden, und es gibt nur sehr wenige Daten.","stillzeit":"Nicht empfohlen – Dienogest geht in die Muttermilch über.","hinweise":["Täglich ohne Pause etwa zur gleichen Zeit einnehmen.","Visanne ist kein Verhütungsmittel: Falls Verhütung nötig ist, eine nichthormonale Methode (z. B. Kondom) verwenden.","Bei Erbrechen oder Durchfall innerhalb von 3–4 Stunden nach der Einnahme kann die Wirkung vermindert sein.","Unregelmässige Blutungen sind besonders in den ersten Monaten häufig; anhaltend starke Blutungen ärztlich abklären lassen."],"darreichung":["Tabletten"]},"digoxin":{"wirkmechanismus":"Verlangsamt einen zu schnellen Puls und verstärkt die Pumpkraft des Herzmuskels. Digoxin hemmt die Natrium-Kalium-Pumpe (Na+/K+-ATPase) der Herzmuskelzellen; dadurch steigt über den Natrium-Calcium-Austauscher die Calciumkonzentration in der Zelle, was die Kontraktionskraft erhöht (positiv inotrop). Zusätzlich verstärkt Digoxin den Einfluss des Vagusnervs und verlangsamt so die Überleitung im AV-Knoten, wodurch bei Vorhofflimmern weniger Impulse auf die Herzkammern übertragen werden. Die therapeutische Breite ist sehr eng; Digoxin wird überwiegend unverändert über die Niere ausgeschieden.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen, Durchfall","Schwindel und andere Störungen des Nervensystems","Sehstörungen (verschwommenes Sehen, Gelb- oder Grünsehen)","Herzrhythmusstörungen (z. B. Extraschläge, Bigeminus), Bradykardie (verlangsamter Herzschlag) und Leitungsstörungen","Hautausschlag (Nesselsucht-artig oder scharlachartig)"],"gelegentlich":["Depression"],"sehrSelten":["Thrombozytopenie (Mangel an Blutplättchen)","Appetitlosigkeit","Verwirrtheit, Apathie, Psychose","Kopfschmerzen","Gefährliche Herzrhythmusstörungen (Vorhof- und Kammertachykardien)","Durchblutungsstörung oder Absterben von Darmabschnitten (Darmischämie)","Gynäkomastie (Brustvergrösserung beim Mann) bei Langzeitbehandlung","Müdigkeit, Schwäche, Unwohlsein"]},"schwangerschaft":"Kann in der Schwangerschaft angewendet werden, wenn es nötig ist; Digoxin gelangt zum Kind. Der Spiegel muss überwacht werden, da sich der Bedarf ändern kann.","stillzeit":"Geht nur in geringer Menge in die Muttermilch über; Stillen ist erlaubt.","hinweise":["Regelmässige Kontrollen von Digoxinspiegel, Kalium und Nierenfunktion sind wichtig.","Warnzeichen einer Überdosierung: Übelkeit, Appetitlosigkeit, Sehstörungen (Gelb- oder Grünsehen), Verwirrtheit, sehr langsamer oder unregelmässiger Puls – sofort ärztlich melden.","Antazida und Colestyramin mit mindestens 2 Stunden Abstand einnehmen; keine Johanniskraut-Präparate.","Jedes neue Medikament, auch Antibiotika, ärztlich auf Wechselwirkungen prüfen lassen."],"darreichung":["Tabletten","Injektionslösung"]},"diltiazem":{"wirkmechanismus":"Entlastet das Herz, senkt den Blutdruck und verlangsamt den Puls, indem es den Calcium-Einstrom in Herz- und Gefässmuskelzellen hemmt. Diltiazem blockiert L-Typ-Calciumkanäle: Es erweitert die Herzkranz- und peripheren Arterien, verhindert Gefässkrämpfe und senkt so den Sauerstoffbedarf des Herzens. Zusätzlich bremst es die Erregungsbildung im Sinusknoten und die Überleitung im AV-Knoten. Diltiazem wird über CYP3A4 abgebaut und hemmt dieses Enzym mässig.","nebenwirkungen":{"sehrHaeufig":["Periphere Ödeme (Wassereinlagerungen, vor allem an den Knöcheln)"],"haeufig":["Kopfschmerzen, Schwindel","AV-Block (verlangsamte Erregungsleitung im Herzen)","Herzklopfen","Flush (Gesichtsrötung mit Wärmegefühl)","Verstopfung, Verdauungsstörungen, Magenschmerzen, Übelkeit","Hautrötung (Erythem)","Unwohlsein, Müdigkeit"],"gelegentlich":["Bradykardie (langsamer Puls)","Blutdruckabfall beim Aufstehen","Nervosität, Schlaflosigkeit","Erbrechen, Durchfall","Erhöhte Leberwerte"],"selten":["Mundtrockenheit","Nesselsucht (Urtikaria)"],"unbekannt":["Sinusknotenstillstand, sinuatrialer Block, Herzstillstand, Verschlechterung einer Herzschwäche","Thrombozytopenie (Mangel an Blutplättchen)","Stimmungsschwankungen einschliesslich Depression; extrapyramidale Bewegungsstörungen","Hepatitis; Zahnfleischwucherung (Gingivahyperplasie)","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, AGEP, exfoliative Dermatitis)","Angioödem, Lichtempfindlichkeit, Vaskulitis (Gefässentzündung)","Brustvergrösserung beim Mann, vermehrtes Schwitzen"]},"schwangerschaft":"Kontraindiziert (im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter sollen während der Behandlung zuverlässig verhüten.","stillzeit":"Diltiazem geht in die Muttermilch über; während der Behandlung nicht stillen.","hinweise":["Retardform unzerkaut mit Flüssigkeit schlucken.","Puls regelmässig messen; bei sehr langsamem Puls, Schwindel oder Ohnmacht ärztlich melden.","Kann die Fahrtüchtigkeit beeinträchtigen, besonders zu Beginn der Behandlung.","Vor Operationen und beim Beginn neuer Medikamente die Einnahme angeben – Diltiazem hat viele Wechselwirkungen."],"darreichung":["Tabletten bzw. Kapseln mit verzögerter Freisetzung (Retardform)"]},"dimethylfumarat":{"wirkmechanismus":"Dämpft überschiessende Entzündungs- und Immunreaktionen. Dimethylfumarat wird im Darm rasch in Monomethylfumarat umgewandelt, den eigentlichen Wirkstoff. Dieser aktiviert den Nrf2-Signalweg, der Zellen vor oxidativem Stress schützt, hemmt entzündungsfördernde Signale (NF-kappaB) und verschiebt die Immunantwort von entzündlichen Th1- und Th17-Zellen hin zu Th2-Zellen. Zudem sinkt die Zahl der Lymphozyten im Blut.","nebenwirkungen":{"sehrHaeufig":["Flush (Hitzegefühl mit Hautrötung)","Durchfall, Übelkeit","Bauchschmerzen, Blähungen","Lymphopenie und Leukopenie (Mangel an weissen Blutkörperchen; vor allem unter Psoriasis-Therapie sehr häufig)"],"haeufig":["Erbrechen, Verdauungsbeschwerden, Magenschleimhautentzündung, Magen-Darm-Infekt","Juckreiz, Ausschlag, Hautrötung, Brennen der Haut","Kopfschmerzen, Kribbeln (Parästhesien)","Erhöhte Leberwerte","Eiweiss und Ketone im Urin (Proteinurie, Ketonurie)","Müdigkeit, Schwäche, Hitzegefühl","Eosinophilie (Anstieg bestimmter weisser Blutkörperchen)","Appetitminderung"],"gelegentlich":["Überempfindlichkeitsreaktionen","Thrombozytopenie (Mangel an Blutplättchen)","Schwindel","Erhöhtes Kreatinin im Blut"],"unbekannt":["Progressive multifokale Leukenzephalopathie (PML, schwere Hirninfektion)","Gürtelrose (Herpes zoster) und andere opportunistische Infektionen","Anaphylaxie, Angioödem, Atemnot","Arzneimittelbedingte Leberschädigung","Fanconi-Syndrom (Nierenschaden)","Laufende Nase"]},"schwangerschaft":"Multiple Sklerose: nur nach sorgfältiger ärztlicher Abwägung, wenn klar notwendig. Psoriasis-Präparat (Skilarence): kontraindiziert, Frauen im gebärfähigen Alter müssen sicher verhüten.","stillzeit":"Unklar, ob der Wirkstoff in die Muttermilch übergeht: bei MS nur nach ärztlicher Abwägung; das Psoriasis-Präparat ist in der Stillzeit kontraindiziert.","hinweise":["Mit einer Mahlzeit einnehmen und unzerkaut schlucken – das mildert Flush und Magen-Darm-Beschwerden; die Dosis wird zu Beginn langsam gesteigert.","Blutbild (Lymphozyten) vor Beginn und regelmässig, mindestens alle 3 Monate, sowie Leber- und Nierenwerte und Urin kontrollieren lassen.","Neue oder zunehmende neurologische Beschwerden (Schwäche, Seh-, Sprach- oder Gedächtnisstörungen) sofort melden.","Keine hochprozentigen alkoholischen Getränke innerhalb einer Stunde nach der Einnahme."],"darreichung":["Magensaftresistente Hartkapseln (Multiple Sklerose)","Magensaftresistente Tabletten (Psoriasis)"]},"dimetinden":{"wirkmechanismus":"Lindert Juckreiz und allergische Beschwerden, indem es den Botenstoff Histamin blockiert. Dimetinden ist ein Antagonist am Histamin-H1-Rezeptor und vermindert so Gefässdurchlässigkeit, Quaddelbildung, Rötung und Juckreiz. Auf der Haut wirkt es zusätzlich leicht örtlich betäubend, weshalb das Gel Juckreiz rasch lindert. Eingenommen gelangt es ins Gehirn und macht deshalb müde; zudem hat es schwache anticholinerge Wirkungen.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit (Tropfen)"],"haeufig":["Schläfrigkeit, Benommenheit (Tropfen)","Nervosität (Tropfen)"],"selten":["Unruhe, Erregung","Kopfschmerzen, Schwindel","Übelkeit, Magen-Darm-Beschwerden","Mund- und Rachentrockenheit"],"sehrSelten":["Anaphylaktische Reaktionen mit Schwellung von Gesicht und Rachen","Hautausschlag","Muskelkrämpfe","Atembeschwerden"],"unbekannt":["Trockene Haut und Brennen an der Auftragsstelle (Gel)","Allergische Hautreaktionen (Gel)","Brennen und Trockenheit der Nasenschleimhaut (Vibrocil)"]},"schwangerschaft":"Tropfen nur nach ärztlicher Abwägung, besonders im 1. Drittel zurückhaltend. Gel kleinflächig nach Abwägung möglich, nicht auf grosse, entzündete oder verletzte Hautflächen.","stillzeit":"Tropfen nicht empfohlen (Übergang in die Muttermilch, Müdigkeit beim Säugling möglich). Gel nicht auf die Brust auftragen.","hinweise":["Die Tropfen machen müde: Fahrtüchtigkeit und Reaktionsvermögen können eingeschränkt sein, besonders zusammen mit Alkohol.","Gel: bei grossflächiger Anwendung behandelte Haut nicht der Sonne aussetzen; bei Juckreiz, der nach einigen Tagen nicht bessert oder grosse Flächen betrifft, Arzt aufsuchen.","Vibrocil (mit Phenylephrin) ohne ärztlichen Rat nicht länger als 7 Tage anwenden – sonst droht eine dauerhaft verstopfte Nase."],"darreichung":["Tropfen zum Einnehmen","Gel","Roll-on","Nasenspray, Nasentropfen, Nasengel (Kombi mit Phenylephrin)"]},"diosmin":{"wirkmechanismus":"Stärkt die Venenwände und verringert Schwellungen in den Beinen. Die mikronisierte Flavonoidfraktion (90 % Diosmin, 10 % weitere Flavonoide, ausgedrückt als Hesperidin) erhöht die Spannung der Venenwand, indem sie die Wirkung von Noradrenalin an der Venenwand verlängert. Zudem vermindert sie die Durchlässigkeit und Brüchigkeit der kleinsten Blutgefässe (Kapillaren), hemmt das Anhaften weisser Blutkörperchen an der Gefässwand und die damit verbundene Entzündung und fördert den Lymphabfluss. Die Mikronisierung verbessert die Aufnahme aus dem Darm.","nebenwirkungen":{"haeufig":["Durchfall","Dyspepsie (Verdauungsbeschwerden)","Übelkeit, Erbrechen"],"gelegentlich":["Kolitis (Dickdarmentzündung)"],"selten":["Schwindel, Kopfschmerzen, Unwohlsein","Hautausschlag, Juckreiz, Nesselsucht"],"unbekannt":["Bauchschmerzen","Schwellung von Gesicht, Lippen oder Augenlidern, ausnahmsweise Angioödem (Quincke-Ödem)"]},"schwangerschaft":"Im Tierversuch keine schädlichen Wirkungen, beim Menschen nur begrenzte Erfahrungen; vorsichtshalber in der Schwangerschaft möglichst nicht anwenden.","stillzeit":"Nicht bekannt, ob der Wirkstoff in die Muttermilch übergeht; Stillen während der Behandlung wird nicht empfohlen.","hinweise":["Zu den Mahlzeiten einnehmen.","Wirkt am besten zusammen mit Kompressionsstrümpfen, regelmässiger Bewegung, Hochlagern der Beine und Meiden von Hitze und langem Stehen.","Bei Hämorrhoidalattacken nur kurzfristig in der höheren Dosierung einnehmen; ohne rasche Besserung ärztlich abklären lassen."],"darreichung":["Filmtabletten"]},"dolutegravir":{"wirkmechanismus":"Verhindert, dass HIV sein Erbgut in die menschlichen Zellen einbaut. Dolutegravir bindet an das aktive Zentrum der viralen Integrase und blockiert den Strangtransfer, mit dem die virale DNA in die DNA der Wirtszelle eingefügt wird; ohne diesen Schritt kann sich das Virus nicht vermehren. Dolutegravir hat eine hohe Resistenzbarriere. Es hemmt zudem den Nierentransporter OCT2, was den Kreatininwert leicht erhöht, ohne die Nierenfunktion zu verschlechtern.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Übelkeit","Durchfall"],"haeufig":["Schlaflosigkeit, abnorme Träume","Depression, Angst","Schwindel, Schläfrigkeit","Erbrechen, Blähungen, Bauchschmerzen","Hautausschlag, Juckreiz","Müdigkeit","Erhöhte Leberwerte und Kreatinkinase (CK)","Gewichtszunahme"],"gelegentlich":["Überempfindlichkeitsreaktionen (Ausschlag, Fieber, Organbeteiligung)","Hepatitis (Leberentzündung)","Suizidgedanken oder Suizidversuch (vor allem bei Depression in der Vorgeschichte)","Panikattacken","Gelenk- und Muskelschmerzen","Immunrekonstitutionssyndrom"],"selten":["Akutes Leberversagen","Erhöhtes Bilirubin","Suizid (bei psychischer Vorerkrankung)"]},"schwangerschaft":"Kann bei klinischer Notwendigkeit in der Schwangerschaft angewendet werden. Ein früher vermutetes erhöhtes Risiko für Neuralrohrdefekte bei Einnahme zum Zeitpunkt der Empfängnis hat sich in grösseren Untersuchungen nicht klar bestätigt – Schwangerschaft mit der HIV-Fachperson planen.","stillzeit":"HIV-positive Mütter sollen grundsätzlich nicht stillen (Übertragungsrisiko); ein Stillwunsch ist mit der HIV-Fachperson zu besprechen.","hinweise":["Mit oder ohne Mahlzeit einnehmen; keine Dosis auslassen.","Antazida, Magnesium-, Eisen-, Calcium- oder Zinkpräparate und Multivitamine nur zeitversetzt (Dolutegravir 2 Stunden davor oder 6 Stunden danach).","Bei Hautausschlag mit Fieber, Blasen, Gelenkschmerzen oder Gelbsucht sofort ärztlich melden.","Ein leicht erhöhter Kreatininwert zu Beginn ist meist harmlos (Hemmung eines Nierentransporters)."],"darreichung":["Filmtabletten"]},"dolutegravir-lamivudin":{"wirkmechanismus":"Hemmt die Vermehrung von HIV an zwei Stellen. Dolutegravir blockiert die Integrase und verhindert den Einbau der Virus-DNA in das Erbgut der Wirtszelle (Strangtransfer). Lamivudin, ein Cytidin-Analogon, wird in den Zellen zum Triphosphat aktiviert, von der Reversen Transkriptase in die Virus-DNA eingebaut und führt zum Kettenabbruch. Dank der hohen Resistenzbarriere von Dolutegravir genügen bei geeigneten Personen zwei Wirkstoffe.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel, Schläfrigkeit","Übelkeit, Durchfall, Erbrechen, Blähungen, Bauchschmerzen","Schlaflosigkeit, abnorme Träume","Depression, Angst","Hautausschlag, Juckreiz, Haarausfall","Gelenk- und Muskelbeschwerden","Müdigkeit","Erhöhte Leberwerte und Kreatinkinase (CK), Gewichtszunahme"],"gelegentlich":["Überempfindlichkeitsreaktionen","Hepatitis (Leberentzündung)","Suizidgedanken oder Suizidversuch, Panikattacken (vor allem bei psychischer Vorerkrankung)","Neutropenie, Anämie, Thrombozytopenie","Immunrekonstitutionssyndrom"],"selten":["Akutes Leberversagen","Pankreatitis (Bauchspeicheldrüsenentzündung)","Rhabdomyolyse (Muskelzerfall)","Angioödem (Schwellung von Haut und Schleimhäuten)","Laktatazidose (Übersäuerung des Blutes)","Suizid (bei psychischer Vorerkrankung)"],"sehrSelten":["Periphere Neuropathie (Kribbeln, Taubheitsgefühl)","Erythroblastopenie (Aplasie der roten Blutzellen)"]},"schwangerschaft":"Kann bei klinischer Notwendigkeit angewendet werden. Ein früher vermutetes erhöhtes Risiko für Neuralrohrdefekte durch Dolutegravir zum Zeitpunkt der Empfängnis hat sich in grösseren Untersuchungen nicht klar bestätigt – Schwangerschaft mit der HIV-Fachperson planen.","stillzeit":"HIV-positive Mütter sollen grundsätzlich nicht stillen (Übertragungsrisiko); ein Stillwunsch ist mit der HIV-Fachperson zu besprechen.","hinweise":["Einmal täglich mit oder ohne Mahlzeit einnehmen; keine Dosis auslassen.","Antazida, Magnesium-, Eisen-, Calcium- oder Zinkpräparate und Multivitamine nur zeitversetzt (Dovato 2 Stunden davor oder 6 Stunden danach).","Vor Beginn auf Hepatitis B testen; bei Hepatitis B nicht eigenmächtig absetzen.","Ein leicht erhöhter Kreatininwert zu Beginn ist meist harmlos (Hemmung eines Nierentransporters)."],"darreichung":["Filmtabletten"]},"domperidon":{"wirkmechanismus":"Wirkt gegen Übelkeit und beschleunigt die Weitergabe des Mageninhalts in den Darm. Domperidon blockiert Dopamin-D2-Rezeptoren in der Brechreizzone (Chemorezeptor-Triggerzone), die ausserhalb der Blut-Hirn-Schranke liegt, sowie im Magen. Dadurch steigen Magenbeweglichkeit und Druck des unteren Speiseröhren-Schliessmuskels. Da es kaum ins Gehirn gelangt, sind Bewegungsstörungen seltener als bei Metoclopramid; über die Hypophyse kann es jedoch das Prolaktin erhöhen. In höheren Spiegeln hemmt es Kaliumkanäle im Herzen (hERG) und verlängert die QT-Zeit.","nebenwirkungen":{"haeufig":["Mundtrockenheit"],"gelegentlich":["Kopfschmerzen, Schläfrigkeit","Angst, Libidoverlust","Durchfall","Hautausschlag, Juckreiz","Milchfluss aus der Brust (Galaktorrhö), Brustschmerzen und -spannen","Schwächegefühl (Asthenie)"],"unbekannt":["Ventrikuläre Herzrhythmusstörungen, QT-Verlängerung, Torsade de pointes, plötzlicher Herztod","Krampfanfälle, extrapyramidale Bewegungsstörungen, Blickkrämpfe","Unruhe, Nervosität","Anaphylaxie, Angioödem, Nesselsucht","Brustvergrösserung beim Mann (Gynäkomastie), Ausbleiben der Regelblutung","Harnverhalt","Erhöhte Leberwerte und erhöhtes Prolaktin im Blut"]},"schwangerschaft":"Nur begrenzte Erfahrungen; in der Schwangerschaft nur anwenden, wenn der Nutzen das Risiko klar überwiegt.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; ein Risiko für Herznebenwirkungen beim Säugling ist nicht ausgeschlossen. Nur nach ärztlicher Abwägung.","hinweise":["Höchstdosis 30 mg pro Tag (meist 3 × 10 mg); in der Regel nicht länger als eine Woche anwenden.","Vor den Mahlzeiten einnehmen; Schmelztabletten auf der Zunge zergehen lassen.","Alle anderen Medikamente angeben – viele erhöhen zusammen mit Domperidon das Risiko für Herzrhythmusstörungen.","Bei Herzklopfen, Schwindel oder Ohnmacht sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten","Schmelztabletten"]},"doxazosin":{"wirkmechanismus":"Entspannt die Muskulatur in den Blutgefässen sowie in Prostata und Blasenhals. Doxazosin blockiert selektiv und kompetitiv Alpha-1-Rezeptoren, über die Noradrenalin normalerweise die glatte Muskulatur zusammenzieht. In den Gefässen sinkt dadurch der Widerstand und damit der Blutdruck; in Prostata und Blasenhals lässt der Druck auf die Harnröhre nach, sodass der Urin leichter abfliesst. Die erste Dosis kann einen deutlichen Blutdruckabfall auslösen (First-Dose-Effekt).","nebenwirkungen":{"haeufig":["Schwindel, Drehschwindel, Kopfschmerzen, Schläfrigkeit","Blutdruckabfall, auch beim Aufstehen (orthostatische Hypotonie)","Herzklopfen, Herzrasen","Atemwegsinfekte, Schnupfen, Husten, Atemnot","Bauchschmerzen, Verdauungsbeschwerden, Übelkeit, Mundtrockenheit","Harnwegsinfekt, Blasenentzündung, Harninkontinenz","Schwäche, grippeähnliche Beschwerden, Brustschmerzen, Wassereinlagerungen in den Beinen","Rücken- und Muskelschmerzen, Juckreiz"],"gelegentlich":["Ohnmacht (Synkope), Zittern","Angina pectoris, Herzinfarkt","Schlaganfall","Angst, Depression, Schlaflosigkeit","Verstopfung, Durchfall, Erbrechen, Blähungen","Nasenbluten","Erhöhte Leberwerte","Gewichtszunahme, Gicht","Erektionsstörungen"],"sehrSelten":["Leukopenie und Thrombozytopenie (Mangel an weissen Blutkörperchen bzw. Blutplättchen)","Bradykardie, Herzrhythmusstörungen","Bronchospasmus","Leberentzündung, Cholestase (Gallenstau), Gelbsucht","Priapismus (schmerzhafte Dauererektion)","Verschwommenes Sehen, Haarausfall, Nesselsucht"],"unbekannt":["Intraoperatives Floppy-Iris-Syndrom bei Kataraktoperation","Retrograde Ejakulation (Samenerguss in die Blase)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; es gibt kaum Erfahrungen bei Schwangeren.","stillzeit":"Geht in die Muttermilch über; Anwendung in der Stillzeit nicht empfohlen.","hinweise":["Die erste Dosis kann starken Schwindel oder eine Ohnmacht auslösen – Behandlung mit niedriger Dosis beginnen, zu Beginn kein Auto fahren und langsam aufstehen.","Vor einer Operation am grauen Star die Augenärztin oder den Augenarzt über die Einnahme informieren.","Retardtabletten ganz schlucken, nicht teilen oder kauen; die leere Tablettenhülle kann im Stuhl erscheinen.","Bei einer schmerzhaften Dauererektion sofort ärztliche Hilfe holen."],"darreichung":["Tabletten","Retardtabletten"]},"doxycyclin":{"wirkmechanismus":"Hemmt das Wachstum und die Vermehrung von Bakterien. Doxycyclin bindet an die 30S-Untereinheit der bakteriellen Ribosomen und verhindert die Anlagerung der Aminoacyl-tRNA; dadurch wird die Eiweissbildung der Bakterien blockiert (bakteriostatische Wirkung). Das Spektrum umfasst viele grampositive und gramnegative Keime sowie Erreger, die in Zellen leben, wie Chlamydien, Mykoplasmen und Rickettsien, ausserdem Borrelien. Doxycyclin ist gut fettlöslich, wird fast vollständig aufgenommen und reichert sich auch bei eingeschränkter Nierenfunktion kaum an.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen","Kopfschmerzen","Photosensibilität (sonnenbrandähnliche Hautreaktion bei Licht)","Hautausschlag","Überempfindlichkeitsreaktionen (z. B. Nesselsucht, Schwellungen, in schweren Fällen Anaphylaxie)"],"gelegentlich":["Dyspepsie (Sodbrennen, Magenschleimhautreizung)"],"selten":["Speiseröhrenentzündung und -geschwüre, Schluckbeschwerden","Durchfall, Bauchschmerzen, Zungenentzündung","Pseudomembranöse Kolitis (schwere Darmentzündung durch Clostridioides difficile)","Erhöhter Hirndruck (Pseudotumor cerebri) mit Kopfschmerzen und Sehstörungen","Leberentzündung, erhöhte Leberwerte","Blutbildveränderungen (hämolytische Anämie, Thrombozytopenie, Neutropenie)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Pankreatitis, Herzbeutelentzündung, Gelenk- und Muskelschmerzen, Ohrensausen"],"unbekannt":["Bleibende Zahnverfärbung und Zahnschmelzschäden bei Kindern unter 8 Jahren","Pilzinfektionen (Mund, Scheide)","Jarisch-Herxheimer-Reaktion (Fieber, Schüttelfrost) bei Borreliose oder Syphilis"]},"schwangerschaft":"Kontraindiziert: Doxycyclin kann beim ungeborenen Kind zu bleibender Zahnverfärbung und Störungen des Knochenwachstums führen, vor allem ab dem 4. Schwangerschaftsmonat.","stillzeit":"Kontraindiziert: geht in die Muttermilch über (Zahnverfärbung und Störung des Knochenwachstums beim Säugling möglich).","hinweise":["Mit einem grossen Glas Wasser in aufrechter Haltung einnehmen und danach mindestens 30 Minuten nicht hinlegen – nicht direkt vor dem Schlafengehen (Gefahr von Speiseröhrengeschwüren). Einnahme zu einer Mahlzeit verbessert die Magenverträglichkeit.","Calcium-, Magnesium-, Eisen- und Zinkpräparate sowie Antazida mit 2–3 Stunden Abstand einnehmen; grössere Mengen Milchprodukte nicht gleichzeitig.","Während der Behandlung und einige Tage danach starke Sonne und Solarium meiden, guten Sonnenschutz verwenden.","Bei starken Kopfschmerzen mit Sehstörungen oder bei schwerem, anhaltendem Durchfall sofort ärztlichen Rat einholen."],"darreichung":["Tabletten","Lösliche Tabletten"]},"dulaglutid":{"wirkmechanismus":"Wirkt wie das körpereigene Darmhormon GLP-1, das nach dem Essen ausgeschüttet wird. Dulaglutid besteht aus zwei GLP-1-ähnlichen Peptidketten, die an ein verändertes Antikörperstück (Fc-Teil von IgG4) gekoppelt sind; dadurch wird es nur langsam abgebaut und wirkt eine Woche lang. Es steigert blutzuckerabhängig die Insulinausschüttung, hemmt die Glukagonfreisetzung, verlangsamt die Magenentleerung und verstärkt das Sättigungsgefühl. In einer grossen Studie senkte es bei Typ-2-Diabetes das Risiko schwerer Herz-Kreislauf-Ereignisse.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Durchfall","Erbrechen","Bauchschmerzen","Hypoglykämie (Unterzuckerung) in Kombination mit Insulin oder Sulfonylharnstoff"],"haeufig":["Appetitminderung","Verdauungsbeschwerden, Verstopfung, Blähungen, Völlegefühl, Reflux, Aufstossen","Müdigkeit (Fatigue)","Sinustachykardie (erhöhter Puls)","AV-Block 1. Grades (leichte Verzögerung der Erregungsleitung im Herzen, im EKG sichtbar)"],"gelegentlich":["Überempfindlichkeitsreaktionen","Dehydratation (Flüssigkeitsmangel)","Gallensteine (Cholelithiasis) und Cholezystitis (Gallenblasenentzündung)","Reaktionen an der Injektionsstelle"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Angioödem (Schwellung von Gesicht, Lippen oder Rachen)","Akute Pankreatitis (Bauchspeicheldrüsenentzündung)"],"unbekannt":["Nicht-mechanischer Darmverschluss (Ileus)"]},"schwangerschaft":"Nicht anwenden: Die Erfahrungen sind unzureichend, Tierversuche zeigten Fruchtschädigung. Bei Diabetes in der Schwangerschaft wird Insulin eingesetzt.","stillzeit":"Nicht anwenden, da nicht bekannt ist, ob Dulaglutid in die Muttermilch übergeht.","hinweise":["Einmal pro Woche am gleichen Wochentag spritzen, unabhängig vom Essen; der Wochentag kann gewechselt werden, wenn seit der letzten Dosis mindestens 3 Tage vergangen sind.","Vergessene Dosis nachholen, wenn bis zur nächsten planmässigen Dosis noch mindestens 3 Tage (72 Stunden) bleiben, sonst auslassen.","Bei anhaltenden, starken Bauchschmerzen sofort ärztlich abklären lassen; bei Übelkeit, Erbrechen oder Durchfall ausreichend trinken.","Vor Operationen, Narkosen oder Magenspiegelungen die Behandlung angeben."],"darreichung":["Injektionslösung im Fertigpen (Einzeldosis)"]},"dutasterid":{"wirkmechanismus":"Lässt eine vergrösserte Prostata schrumpfen, indem es die Bildung des stark wirksamen Androgens Dihydrotestosteron (DHT) unterdrückt. Dutasterid hemmt beide Formen des Enzyms 5-Alpha-Reduktase (Typ 1 und Typ 2), die Testosteron in DHT umwandeln; der DHT-Spiegel im Blut sinkt um über 90 %. Das Prostatavolumen nimmt über Monate ab, die Beschwerden bessern sich meist nach 3–6 Monaten. Wegen der sehr langen Halbwertszeit von etwa 5 Wochen bleibt der Wirkstoff nach dem Absetzen noch monatelang im Körper.","nebenwirkungen":{"haeufig":["Erektionsstörung (Impotenz)","Verminderte Libido (Lust auf Sex)","Ejakulationsstörungen, z. B. vermindertes Spermavolumen","Brustbeschwerden (Spannungsgefühl, Vergrösserung)","Schwindel (in Kombination mit Tamsulosin)"],"gelegentlich":["Haarausfall (v. a. Körperbehaarung) oder vermehrter Haarwuchs"],"unbekannt":["Herzinsuffizienz (in Studien, v. a. in Kombination mit Alpha-Blockern)","Überempfindlichkeitsreaktionen mit Ausschlag, Juckreiz, Nesselsucht, Angioödem","Depressive Verstimmung","Hodenschmerzen und Hodenschwellung","Brustkrebs beim Mann"]},"schwangerschaft":"Kontraindiziert. Der Wirkstoff wird über die Haut aufgenommen: Frauen, Kinder und Jugendliche sollen beschädigte, undichte Kapseln nicht berühren (sonst die Haut sofort mit Wasser und Seife waschen). Da Dutasterid ins Sperma übergeht, soll ein Kondom benutzt werden, wenn die Partnerin schwanger ist oder schwanger werden könnte.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Kapseln ganz schlucken, nicht kauen oder öffnen – der Inhalt reizt die Schleimhaut von Mund und Rachen.","Während der Behandlung und bis mindestens 6 Monate nach der letzten Einnahme kein Blut spenden.","Bei einer PSA-Bestimmung die Einnahme angeben.","Die Wirkung ist oft erst nach 3–6 Monaten spürbar; nicht vorzeitig absetzen."],"darreichung":["Weichkapseln"]},"dydrogesteron":{"wirkmechanismus":"Wirkt wie das körpereigene Gelbkörperhormon und bringt die Gebärmutterschleimhaut in die zweite Zyklusphase. Dydrogesteron ist ein oral wirksames Retroprogesteron, das sehr selektiv an Progesteronrezeptoren bindet und die durch Östrogen aufgebaute Schleimhaut in eine sekretorische Schleimhaut umwandelt. Es hat keine östrogene, androgene oder kortisonartige Wirkung und hemmt in üblicher Dosis den Eisprung nicht. Sein Hauptabbauprodukt (20-alpha-Dihydrodydrogesteron) ist ebenfalls gestagen wirksam.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Migräne","Übelkeit","Menstruationsstörungen (Zwischenblutungen, starke, schmerzhafte oder ausbleibende Blutungen)","Brustschmerzen oder Brustspannen"],"gelegentlich":["Depressive Verstimmung","Schwindel","Erbrechen","Leberfunktionsstörungen, teils mit Gelbsucht, Schwäche und Bauchschmerzen","Allergische Hautreaktionen (Ausschlag, Juckreiz, Nesselsucht)","Gewichtszunahme"],"selten":["Hämolytische Anämie (Blutarmut durch Zerfall roter Blutkörperchen)","Überempfindlichkeitsreaktionen","Schläfrigkeit","Angioödem (Schwellung von Gesicht und Rachen)","Wassereinlagerungen (Ödeme)","Brustschwellung","Grössenzunahme gestagenabhängiger Tumoren (z. B. Meningeom)"]},"schwangerschaft":"Je nach Präparat bei drohender Fehlgeburt infolge nachgewiesenen Progesteronmangels zugelassen und nur auf ärztliche Verordnung anzuwenden; ein schädigender Einfluss auf das Kind ist nicht belegt. Kombinationen mit Östrogen (Femoston) sind in der Schwangerschaft nicht angezeigt.","stillzeit":"Nicht anwenden – es ist nicht bekannt, ob Dydrogesteron in die Muttermilch übergeht.","hinweise":["Tabletten unabhängig von den Mahlzeiten mit etwas Flüssigkeit einnehmen; den vorgegebenen Zyklustagen genau folgen.","Dydrogesteron hemmt den Eisprung nicht und schützt nicht vor einer Schwangerschaft.","Bei Hormonersatz Nutzen und Risiken mindestens jährlich ärztlich überprüfen lassen; ungewöhnliche Blutungen abklären lassen."],"darreichung":["Filmtabletten"]}});
